def read_number(n: int) -> str:
    digits = "일이삼사오육칠팔구"
    units = ["", "십", "백", "천"]

    def group(x: int) -> str:
        # Reads a number 0 < x < 10000 in Sino-Korean.
        out = []
        for i in range(3, -1, -1):  # place index: 3=천, 2=백, 1=십, 0=ones
            d = (x // (10 ** i)) % 10
            if d == 0:
                continue
            unit = units[i]
            if d == 1 and unit:
                out.append(unit)
            else:
                out.append(digits[d - 1] + unit)
        return "".join(out)

    if n == 0:
        return "영"

    result = []
    eok = n // 10**8
    man = (n // 10**4) % 10**4
    low = n % 10**4

    if eok > 0:
        result.append(group(eok) + "억")
    if man > 0:
        if man == 1:
            result.append("만")
        else:
            result.append(group(man) + "만")
    if low > 0:
        result.append(group(low))

    return "".join(result)
